.custom-video-js-container .video-layer .loader-1 .loader-outter {
    -webkit-animation: loader-1-outter 1s cubic-bezier(.42,.61,.58,.41) infinite;
    animation: loader-1-outter 1s cubic-bezier(.42,.61,.58,.41) infinite;
    border: 4px solid #b50136;
    border-bottom: 0;
    border-left-color: transparent;
    border-radius: 50%;
    height: 100%;
    position: absolute;
    width: 100%
}

.custom-video-js-container .video-layer .loader-1 .loader-inner {
    -webkit-animation: loader-1-inner 1s cubic-bezier(.42,.61,.58,.41) infinite;
    animation: loader-1-inner 1s cubic-bezier(.42,.61,.58,.41) infinite;
    border-bottom: 4px solid #b50136;
    border-left: 4px solid #b50136;
    border-radius: 50%;
    border-right: 0;
    border-top: 4px solid transparent;
    height: 18px;
    left: calc(50% - 22px);
    position: absolute;
    top: calc(50% - 24px);
    width: 18px
}

@-webkit-keyframes loader-1-outter {
    0% {
        -webkit-transform: rotate(0deg);
        transform: rotate(0deg)
    }

    to {
        -webkit-transform: rotate(1turn);
        transform: rotate(1turn)
    }
}

@keyframes loader-1-outter {
    0% {
        -webkit-transform: rotate(0deg);
        transform: rotate(0deg)
    }

    to {
        -webkit-transform: rotate(1turn);
        transform: rotate(1turn)
    }
}

@-webkit-keyframes loader-1-inner {
    0% {
        -webkit-transform: rotate(0deg);
        transform: rotate(0deg)
    }

    to {
        -webkit-transform: rotate(-1turn);
        transform: rotate(-1turn)
    }
}

@keyframes loader-1-inner {
    0% {
        -webkit-transform: rotate(0deg);
