.eventFeeds {
    display: block;
    max-height: calc(100vh - 14rem);
    overflow: auto;
    overflow-x: hidden;
    width: 100%
}

@media (max-width: 767px) {
    .eventFeeds {
        max-height:none;
        overflow-x: visible;
        overflow-x: initial;
        overflow-y: visible;
        overflow-y: initial
    }
}

.eventFeeds .createNewPost {
    display: block;
    position: relative
}

@media screen and (min-width: 768px) {
    .eventFeeds .createNewPost {
        padding:0 2rem
    }
}

.eventFeeds .createNewPost .postBox {
    align-items: center;
    background: var(--cardsBGColor);
    border: 1px solid var(--strokeColor);
    display: flex;
    height: 100%;
    justify-content: space-between;
    padding: 1.6rem;
    width: 100%
}

@media (max-width: 768px) {
    .eventFeeds .createNewPost .postBox {
        padding:1.5rem
    }
}

.eventFeeds .createNewPost .postBox .postHead {
    align-items: center;
    display: flex;
    width: 80%
}

.eventFeeds .postFilter {
    align-items: flex-start;
    display: flex;
    height: 6.2rem;
    overflow: hidden;
    padding: 0 1.75rem
}

.eventFeeds .postFilter::-webkit-scrollbar {
    height: 7px
}

.eventFeeds .postFilter:hover {
    overflow-x: auto;
    overflow-y: hidden
}

.eventFeeds .postFilter .filterBy {
    background-color: var(--themeMainColor);
    border-radius: 0 2rem 2rem 0;
    color: #fff;
    font-size: 1.4rem;
    height: 4rem;
    margin-right: 1rem;
    text-transform: uppercase;
    width: 11rem
}

.eventFeeds .postFilter .filterBy,.eventFeeds .postFilter .filterOptions {
    align-items: center;
    display: flex;
    justify-content: center
}

.eventFeeds .postFilter .filterOptions .filter.sm {
    min-width: auto;
    padding: 0 1.25rem
}

@media (max-width: 767px) {
    .eventFeeds .postFilter {
        display:none
    }
}

.eventFeeds .searchBar {
    display: block;
    padding: 1.75rem 0;
    position: relative
}

@media (min-width: 768px) and (max-width:1023px) {
    .eventFeeds .searchBar {
        padding:2rem 0
    }
}

@media screen and (min-width: 1024px) {
    .eventFeeds .searchBar {
        padding:2rem
    }
}

.eventFeeds .searchBar .inputBoxWrapper .inputBox .inputText.rounded.pl3 {
    padding-left: 4.5rem!important;
    padding-right: 1.5rem
}

.eventFeeds .searchBar .searchIconWrapper {
    color: #909090;
    left: 1.5rem;
    position: absolute;
    top: 2.9rem;
    z-index: 9
}

@media screen and (min-width: 768px) {
    .eventFeeds .searchBar .searchIconWrapper {
        left:3.2rem
    }
}

@media (max-width: 768px) {
    .eventFeeds .searchBar {
        align-items:center;
        display: flex;
        justify-content: space-between;
        width: 100%
    }

    .eventFeeds .searchBar .inputBoxWrapper {
        margin-bottom: 0;
        margin-right: 1rem;
        width: 100%
    }
}

.eventFeeds .searchBar .mobileFilter {
    display: none
}

@media (max-width: 767px) {
    .eventFeeds .searchBar .mobileFilter {
        display:flex
    }
}

.eventFeeds .eventFeedList {
    padding: 0 2rem
}

@media (min-width: 768px) and (max-width:1023px) {
    .eventFeeds .eventFeedList {
        padding:0
    }
}

@media (max-width: 640px) {
    .eventFeeds .eventFeedList {
        padding:0
    }
}

.eventFeeds .eventFeedList .eventFeedCard {
    -webkit-animation: sessionSidePanel .3s forwards;
    animation: sessionSidePanel .3s forwards;
    background: var(--cardsBGColor);
    border: 1px solid var(--strokeColor);
    margin-bottom: 2rem;
    min-height: 22rem;
    opacity: 0;
    overflow: hidden;
    padding: 1.6rem;
    position: relative;
    -webkit-transform: translateY(-15px);
    transform: translateY(-15px);
    transition: all .25s;
    width: 100%
}

.eventFeeds .eventFeedList .eventFeedCard:first-child {
    -webkit-animation-delay: .11111s;
    animation-delay: .11111s
}

.eventFeeds .eventFeedList .eventFeedCard:nth-child(2) {
    -webkit-animation-delay: .22222s;
    animation-delay: .22222s
}

.eventFeeds .eventFeedList .eventFeedCard:nth-child(3) {
    -webkit-animation-delay: .33333s;
    animation-delay: .33333s
}

@media (max-width: 640px) {
    .eventFeeds .eventFeedList .eventFeedCard {
        border:.1rem solid var(--strokeColor);
        box-shadow: none
    }
}

.eventFeeds .eventFeedList .eventFeedCard .scheduleCardHead {
    align-items: center;
    display: flex;
    justify-content: space-between
}

.eventFeeds .eventFeedList .eventFeedCard .scheduleCardHead .timeBlock {
    display: flex
}

.eventFeeds .eventFeedList .eventFeedCard .scheduleCardHead .timeBlock svg {
    margin-right: 4px
}

.eventFeeds .eventFeedList .eventFeedCard .scheduleCardHead .statusTag {
    align-items: center;
    border-radius: 5px;
    display: flex;
    font-size: var(--fontSize12);
    font-weight: 700;
    height: 20px;
    justify-content: center;
    letter-spacing: -.257143px;
    line-height: 15px;
    width: 60px
}

.eventFeeds .eventFeedList .eventFeedCard .scheduleCardHead .statusTag.success {
    background: #e2f1dc;
    color: #6cb851
}

.eventFeeds .eventFeedList .eventFeedCard .scheduleCardHead .statusTag.requested {
    background: #fff;
    color: #4e59b8
}

.eventFeeds .eventFeedList .eventFeedCard .bluePinCorner {
    border-bottom: 5rem solid transparent;
    border-right: 6rem solid var(--themeMainColor);
    height: 0;
    position: absolute;
    right: 0;
    top: 0;
    width: 0
}

.eventFeeds .eventFeedList .eventFeedCard .bluePinCorner svg {
    -webkit-animation: bounce1 1s ease;
    animation: bounce1 1s ease;
    -webkit-animation-iteration-count: 4;
    animation-iteration-count: 4;
    color: var(--secondaryFontColor);
    position: absolute;
    right: -4.5rem;
    top: .9rem
}

@-webkit-keyframes bounce1 {
    0%,20%,50%,80%,to {
        -webkit-transform: translateY(0);
        transform: translateY(0)
    }

    40% {
        -webkit-transform: translateY(-2px);
        transform: translateY(-2px)
    }

    60% {
        -webkit-transform: translateY(2px);
        transform: translateY(2px)
    }
}

@keyframes bounce1 {
    0%,20%,50%,80%,to {
        -webkit-transform: translateY(0);
        transform: translateY(0)
    }

    40% {
        -webkit-transform: translateY(-2px);
        transform: translateY(-2px)
    }

    60% {
        -webkit-transform: translateY(2px);
        transform: translateY(2px)
    }
}

.eventFeeds .eventFeedList .eventFeedCard .cardHeader {
    display: flex;
    justify-content: space-between
}

.eventFeeds .eventFeedList .eventFeedCard .cardHeader .userDetails {
    align-items: center;
    display: flex
}

.eventFeeds .eventFeedList .eventFeedCard .cardHeader .userDetails .userPic {
    height: 5rem;
    margin-right: 1rem;
    overflow: hidden;
    width: 5rem
}

.eventFeeds .eventFeedList .eventFeedCard .cardHeader .userDetails .userText {
    display: flex;
    flex-direction: column
}

.eventFeeds .eventFeedList .eventFeedCard .cardHeader .userDetails .userText .userNameText {
    letter-spacing: -.3px;
