    width: 1em
}

.connectLoader .dot:before {
    -webkit-animation: wave 2s ease-out infinite;
    animation: wave 2s ease-out infinite;
    background: inherit;
    border-radius: inherit;
    content: "";
    height: 100%;
    position: absolute;
