.pluseIconAnimation {
    -webkit-animation: pulse 2s infinite;
    animation: pulse 2s infinite;
    position: relative;
    z-index: 1
}

.pluseIconAnimation:after {
    -webkit-animation: pulse2 2s infinite;
    animation: pulse2 2s infinite;
    border-radius: 50%;
    box-shadow: 0 0 0 #cca92c;
    content: "";
    height: 100%;
    left: 0;
    position: absolute;
    top: 0;
    width: 100%;
    z-index: -1
}

@-webkit-keyframes pulse {
    0% {
        box-shadow: 0 0 0 0 hsla(0,0%,100%,.4)
    }

    50% {
        box-shadow: 0 0 0 5px hsla(0,0%,100%,.2)
    }

    to {
        box-shadow: 0 0 0 0 hsla(0,0%,100%,.2)
    }
}

@keyframes pulse {
    0% {
        box-shadow: 0 0 0 0 hsla(0,0%,100%,.4)
    }

    50% {
        box-shadow: 0 0 0 5px hsla(0,0%,100%,.2)
    }

    to {
        box-shadow: 0 0 0 0 hsla(0,0%,100%,.2)
    }
}

@-webkit-keyframes pulse2 {
    0% {
        box-shadow: 0 0 0 0 hsla(0,0%,100%,.4)
    }

    50% {
        box-shadow: 0 0 0 10px hsla(0,0%,100%,.3)
    }

    to {
        box-shadow: 0 0 0 0 hsla(0,0%,100%,.3)
    }
}

@keyframes pulse2 {
    0% {
        box-shadow: 0 0 0 0 hsla(0,0%,100%,.4)
    }

    50% {
        box-shadow: 0 0 0 10px hsla(0,0%,100%,.3)
    }

    to {
        box-shadow: 0 0 0 0 hsla(0,0%,100%,.3)
    }
}

