.loungeListHeader {
    align-items: center;
    display: flex;
    justify-content: space-between;
    position: relative
}

.loungeListHeader .switchLabelText {
    color: var(--primaryColor);
    display: block;
    font-size: 1.4rem;
    font-weight: 500;
    letter-spacing: -.3px;
    line-height: 1.8rem;
    text-align: right;
    width: 100%
}

@media screen and (max-width: 480px) {
    .loungeListHeader .switchLabelText {
        width:auto
    }
}

.loungeListHeader .actionBar {
    z-index: 2
}

@media screen and (max-width: 480px) {
    .loungeListHeader .actionBar {
        margin-top:.7rem
    }

    .loungeListHeader .actionBar .wrapperBox {
        align-items: center;
        justify-content: flex-end;
        width: 47%
    }
}

.loungeListViewWrapper .filtersWrapper {
    margin-top: 1.5rem
}

.loungeListViewWrapper .ml10.position-relative {
    margin-left: 0
}

.loungeListEmptyIcon {
    -webkit-animation: sessionSidePanel .2s forwards;
    animation: sessionSidePanel .2s forwards;
    opacity: 0;
    -webkit-transform: translateY(-15px);
    transform: translateY(-15px);
    transition: all .25s
}

.loungeListEmptyIcon svg {
    width: 100%
}

.loungeJoinedScreen {
    height: 100%;
    left: 0;
    overflow: hidden;
    padding: 1rem 2rem;
    position: absolute;
    top: 0;
    width: 100%
}

.loungeJoinedScreen .messageOverlay {
    background-color: rgba(0,0,0,.5);
    height: 100%;
    left: 0;
    position: absolute;
    top: 0;
    width: 100%
}

.loungeJoinedScreen .joinedMsg {
    align-items: center;
    background: var(--cardsBGColor);
    border: 1px solid var(--strokeColor);
    border-radius: 1.4rem;
    display: flex;
    left: 50%;
    margin-bottom: 2rem;
    max-width: 40rem;
    padding: 1.25rem 2rem;
    position: absolute;
    top: 50%;
    -webkit-transform: translate(-50%,-50%);
    transform: translate(-50%,-50%);
    width: 100%
}

.loungeJoinedScreen .joinedMsg .loungeIcon {
    color: var(--themeMainColor);
    margin-right: 1.5rem
}

.loungeJoinedScreen .joinedMsg .typoText span {
    font-weight: 700
}

.loungeCard {
    background: var(--cardsBGColor);
    border: 1px solid var(--strokeColor);
