.sessionNormalCard {
    align-items: flex-start;
    background: var(--cardsBGColor);
    border: 1px solid var(--strokeColor);
    border-radius: 1.4rem;
    display: flex;
    flex-direction: column;
    font-size: var(--size12);
    font-style: normal;
    font-weight: var(--weightBold);
    letter-spacing: -.257143px;
    line-height: 1.5rem;
    overflow: hidden;
    transition: all .25s
}

.sessionNormalCard .moreTag:hover~.tagTooltip {
    cursor: pointer;
    opacity: 1;
    visibility: visible
}

.sessionNormalCard .liveBadge {
    background-color: #ff0002;
    border-radius: .5rem;
    color: #fff;
    font-size: var(--fontSize12);
    font-weight: var(--weightNormal);
    left: 1.5rem;
    letter-spacing: .3px;
    padding: .2rem .5rem;
    position: absolute;
    text-transform: uppercase;
    top: 1.5rem;
    z-index: 1
}

@media screen and (max-width: 1024px) {
    .sessionNormalCard .liveBadge {
        line-height:normal
    }
}

.sessionNormalCard .sessionNormalImgWrap {
    background: var(--themeMainColor);
    border-radius: .8rem .8rem 0 0;
    height: 14rem;
    overflow: hidden;
    position: relative;
    transition: all .3s
}

.sessionNormalCard .sessionNormalImgWrap .sessionStartIn {
    align-items: center;
    display: flex;
    flex-direction: column;
    height: 100%;
    justify-content: center
}

.sessionNormalCard .sessionNormalImgWrap .sessionStartIn>* {
    border-radius: 2rem;
    color: var(--secondaryFontColor);
    letter-spacing: .5px
}

.sessionNormalCard .sessionNormalImgWrap .circles {
    height: 100%;
    left: 0;
    overflow: hidden;
    position: absolute;
    top: 0;
    width: 100%
}

.sessionNormalCard .sessionNormalImgWrap .circles li {
    -webkit-animation: animateSquares 25s linear infinite;
    animation: animateSquares 25s linear infinite;
    background: hsla(0,0%,100%,.2);
    bottom: -150px;
    display: block;
    height: 20px;
    list-style: none;
    position: absolute;
    width: 20px
}

.sessionNormalCard .sessionNormalImgWrap .circles li:first-child {
    -webkit-animation-delay: 0s;
    animation-delay: 0s;
    height: 80px;
    left: 25%;
    width: 80px
}

.sessionNormalCard .sessionNormalImgWrap .circles li:nth-child(2) {
    -webkit-animation-delay: 2s;
    animation-delay: 2s;
    -webkit-animation-duration: 12s;
    animation-duration: 12s;
    height: 20px;
    left: 10%;
    width: 20px
}

.sessionNormalCard .sessionNormalImgWrap .circles li:nth-child(3) {
    -webkit-animation-delay: 4s;
    animation-delay: 4s;
    height: 20px;
    left: 70%;
