.productServiceCard {
    background: var(--secondaryFontColor);
    border: .1rem solid var(--strokeColor);
    border-radius: 1rem;
    height: 100%;
    max-width: 22.4rem;
    width: 22.4rem
}

.productServiceCard .productServiceCardImg {
    align-items: center;
    display: flex;
    height: 22.4rem;
    justify-content: center;
    max-height: 22.4rem;
    overflow: hidden
}

.productServiceCard .productServiceCardImg img {
    max-height: 22.4rem;
    max-width: 100%
}

.productServiceCard .productServicesContent h6 {
    max-width: 95%;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap
}

.productServiceCard .productServicesContent .boothNameWrapper {
    align-items: center;
    display: flex;
    justify-content: flex-start
}

.productServiceCard .productServicesContent .boothNameWrapper .boothName {
    align-items: center;
    background: var(--themeMainColor);
    border-radius: .5rem;
    color: var(--secondaryFontColor);
    display: flex;
    font-size: var(--size12);
    font-style: normal;
    font-weight: var(--weightBold);
    justify-content: center;
    line-height: 1.5rem;
    margin: .4rem .8rem .4rem 0;
    padding: .3rem .7rem;
    white-space: nowrap
}

.boothSearchWrapper .boothHead {
    justify-content: space-between;
    margin-bottom: 2.5rem;
    position: relative
}

.boothSearchWrapper .boothHead,.boothSearchWrapper .boothHead .boothTabs {
    align-items: center;
    display: flex
}

.boothSearchWrapper .boothHead .boothTabs .tab {
    color: var(--disabledColor);
    cursor: pointer
}

.boothSearchWrapper .boothHead .boothTabs .tab:not(:last-child) {
    margin-right: 3.2rem
}

.boothSearchWrapper .boothHead .boothTabs .tab.activeTab {
    color: var(--primaryColor)
}

.boothSearchWrapper .boothHead .boothAction {
    align-items: center;
    display: flex;
    margin-left: auto
}

.boothSearchWrapper .boothHead .boothAction .searchBtn {
    margin-right: 1.5rem
}

.boothSearchWrapper .boothHead .searchInputWrapper {
    background-color: var(--cardsBGColor);
    height: 4.8rem;
    left: 0;
    opacity: 0;
    position: absolute;
    top: 0;
    transition: all .25s;
