.roomListWrapper {
    margin-top: 1.25rem;
    position: relative;
    transition: all .25s
}

.roomListWrapper.no-scroll .slick-list .slick-track {
    display: inherit;
    margin-left: 0
}

.roomListWrapper.no-scroll .viewAllBtn {
    right: 0
}

.roomListWrapper .slick-slider .roomCardWrapper {
    padding: 0 0 .5rem
}

.roomListWrapper .slick-slider .slick-list {
    margin: 0 -.5rem 0 -1rem
}

.roomListWrapper .slick-next:before,.roomListWrapper .slick-prev:before {
    display: none
}

.roomListWrapper .slick-arrow {
    top: -3.5rem;
    z-index: 1
}

@media (max-width: 768px) {
    .roomListWrapper .slick-arrow {
        display:none
    }
}

.roomListWrapper .slick-arrow.slick-disabled {
    background-color: var(--hoverColor);
    cursor: not-allowed
}

.roomListWrapper .slick-arrow.slick-disabled>svg {
    color: var(--disabledColor)
}

.roomListWrapper .viewAllBtn {
    position: absolute;
    right: 10.8rem;
    top: -5.3rem
}

@media (max-width: 768px) {
    .roomListWrapper .viewAllBtn {
        right:1.5rem
    }
}

.roomListWrapper .slick-arrow {
    position: absolute
}

.roomListWrapper .slick-prev {
    left: auto;
