@keyframes bt-rise {
  from {
    opacity: 0;
    transform: translateY(18px);
  }

  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes bt-pop-in {
  from {
    opacity: 0;
    scale: .94;
    translate: 0 12px;
  }

  to {
    opacity: 1;
    scale: 1;
    translate: 0 0;
  }
}

@keyframes bt-pop-out {
  from {
    opacity: 1;
    scale: 1;
  }

  to {
    opacity: 0;
    scale: .96;
  }
}

@keyframes bt-fade-in {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

@keyframes bt-fade-out {
  from {
    opacity: 1;
  }

  to {
    opacity: 0;
  }
}

@keyframes bt-menu-in {
  from {
    opacity: 0;
    transform: translateY(-6px) scale(.97);
  }

  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes bt-live {
  0% {
    box-shadow: 0 0 0 0 rgba(29, 122, 82, .55);
  }

  70% {
    box-shadow: 0 0 0 7px rgba(29, 122, 82, 0);
  }

  100% {
    box-shadow: 0 0 0 0 rgba(29, 122, 82, 0);
  }
}

