  from {
    opacity: 0;
    scale: .94;
    translate: 0 12px;
  }

  to {
    opacity: 1;
    scale: 1;
    translate: 0 0;
  }
}

@keyframes bt-pop-out {
  from {
    opacity: 1;
    scale: 1;
  }

  to {
    opacity: 0;
    scale: .96;
  }
}

