  --bt-grad-primary-hover: linear-gradient(135deg, #6a47a8 0%, #442b6f 55%, #331f55 100%);
  --bt-grad-soft: linear-gradient(135deg, #f4effb 0%, #e9e1f5 100%);
  --bt-grad-soft-hover: linear-gradient(135deg, #ece4f8 0%, #ddd1ef 100%);
  --bt-grad-tint: linear-gradient(180deg, #fbfafd 0%, #f3eef9 100%);
  --bt-grad-accent: linear-gradient(180deg, var(--bt-orchid) 0%, var(--bt-violet) 45%, var(--bt-primary) 100%);
  --bt-grad-accent-x: linear-gradient(90deg, var(--bt-violet) 0%, var(--bt-primary) 100%);
  --bt-grad-border: linear-gradient(135deg, rgba(109, 74, 194, .55) 0%, var(--bt-line) 35%, var(--bt-line) 65%, rgba(163, 91, 209, .45) 100%);
  --bt-grad-text: linear-gradient(100deg, var(--bt-ink) 0%, var(--bt-primary) 55%, #5b3d93 100%);

  --bt-font: "Plus Jakarta Sans", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;

  --bt-r-sm: 10px;
  --bt-r: 14px;
  --bt-r-lg: 20px;
