  border-radius: 50%;
  background: var(--bt-primary);
  color: #fff;
  box-shadow: 0 14px 30px -12px rgba(58, 37, 95, .8);
  cursor: pointer;
  opacity: 0;
  visibility: hidden;
  transform: translateY(12px) scale(.9);
  transition: opacity var(--bt-med) var(--bt-ease), transform var(--bt-med) var(--bt-ease), visibility 0s linear var(--bt-med);
}
.bt-top.bt-show {
  opacity: 1;
