@keyframes bt-rise {
  from { opacity: 0; transform: translateY(16px); }
  to   { opacity: 1; transform: none; }
}
@keyframes bt-pop-in {
  from { opacity: 0; scale: .94; translate: 0 12px; }
  to   { opacity: 1; scale: 1; translate: 0 0; }
}
@keyframes bt-pop-out {
  from { opacity: 1; scale: 1; }
  to   { opacity: 0; scale: .96; }
}
@keyframes bt-fade-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}
@keyframes bt-fade-out {
  from { opacity: 1; }
  to   { opacity: 0; }
}
@keyframes bt-menu-in {
  from { opacity: 0; transform: translateY(-6px) scale(.97); }
  to   { opacity: 1; transform: none; }
}
@keyframes bt-sheet-up {
  from { transform: translateY(100%); }
  to   { transform: none; }
}

@media (prefers-reduced-motion: reduce) {
  .headerWrapper,
  .headerWrapper *,
  .miniSidedrawerInn *,
  .sidedrawerWrapper,
  .sidedrawerWrapper *,
  .peopleTabHeader *,
  .delegatesTab,
  .delegatesTab *,
  .mobileFilterDrawer *,
  .bottom-sheet__container,
  .peopleSortFilterModel,
  .ReactModalPortal *,
  .mobileNav *,
  .bt-top {
    animation: none !important;
    transition-duration: .01ms !important;
  }
}
